CREATE TABLE IF NOT EXISTS influencers(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),name TEXT NOT NULL,platform TEXT NOT NULL,profile_url TEXT NOT NULL,niche TEXT,audience TEXT,location_if_public TEXT,contact_method TEXT,fit_notes TEXT,source TEXT NOT NULL,status TEXT NOT NULL,last_contact TEXT,next_action TEXT,campaign_ids_json TEXT NOT NULL DEFAULT '[]',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS influencer_contacts(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),influencer_id TEXT NOT NULL REFERENCES influencers(id),contact_type TEXT NOT NULL,value TEXT,source TEXT,consent_status TEXT NOT NULL DEFAULT 'UNKNOWN',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS outreach_messages(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),influencer_id TEXT NOT NULL REFERENCES influencers(id),campaign_id TEXT REFERENCES campaigns(id),idempotency_key TEXT NOT NULL,message_body TEXT NOT NULL,status TEXT NOT NULL,reviewed_by TEXT,sent_at TEXT,created_at TEXT NOT NULL,UNIQUE(workspace_id,idempotency_key));
CREATE TABLE IF NOT EXISTS assets(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),campaign_id TEXT REFERENCES campaigns(id),filename TEXT NOT NULL,mime_type TEXT NOT NULL,asset_type TEXT NOT NULL,platforms_json TEXT NOT NULL DEFAULT '[]',version TEXT NOT NULL,source TEXT NOT NULL,license TEXT,checksum TEXT NOT NULL,storage_ref TEXT NOT NULL,approval_status TEXT NOT NULL DEFAULT 'PENDING',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
